from model import *
c=C(7,'本地航班模块详细设计','第二篇  分模块详细设计')
S(c,'航班工作台与草稿编辑',
P('页面组成与数据绑定','''LocalFlightPage 分为工具条、状态消息、重量卡片、航班信息、载荷燃油以及关联页面入口。页面通过 useLocal 订阅当前状态，用组件局部的 unit 保存质量显示单位。Flight 的字段值由共享状态提供，显示单位则只属于当前页面。

普通字段的 set 函数使用对象展开形成新 Flight，同时把 source 改为 local-manual。质量字段先执行单位转换，再进入同一编辑动作。由此，无论用户修改航班号还是燃油，状态层都能统一撤销旧确认，而不是为每个控件维护不同的失效逻辑。

WeightCards 每次从当前 Flight 调用 weights，显示 OEW、载荷、ZFW 和 TOW。卡片是草稿的即时解释，不保存另一套合计字段。''',diagram=D('components','工作台组件与状态绑定',['LocalFlightPage','Field / massField','WeightCards','useLocal','editFlight','页面局部 unit'],[(0,1,'组织表单'),(0,2,'显示合计'),(3,0,'提供 State'),(1,4,'提交新 Flight'),(5,1,'转换显示')]),table=T('页面区域|读取内容|主要动作','顶部工具条|当前航班|新建、导入、导出、确认\n状态区|notice / storageError|显示反馈\n重量卡片|weights(flight)|即时派生\n航班字段|身份、机场和航路|编辑文本\n载荷燃油|质量和人数|编辑及单位转换\n关联入口|当前上下文|进入地面或参考页')),
P('草稿更新的执行轨迹','''editFlight 用一个新对象替换 state.flight，清空 confirmed，清除旧的 groundChanged 标志，并根据是否已有结果选择通知文字。随后 publish 保存整个本地状态并通知订阅者。已有 Result 可以保留，但其签名与当前输入不再匹配。

清除 groundChanged 不表示地面变化已经被确认。草稿编辑本身已经撤销 confirmed，因此计算入口仍然关闭。两个条件表达不同事实：confirmed 说明当前草稿有没有被确认，groundChanged 说明确认之后外部目标是否又变了。

订阅者集合使用函数引用进行注册与清理。useLocal 在组件挂载时加入更新函数，在卸载时移除，避免切换页面后继续通知已离开的组件。''',diagram=D('sequence','一次燃油字段编辑的内部调用',['质量输入框','editFlight','publish','LocalFlightPage'],[(0,1,'新 rampKg 与完整 Flight'),(1,1,'confirmed 清空'),(1,2,'发布新 State'),(2,2,'保存 localStorage'),(2,3,'通知订阅者'),(3,3,'重算重量卡片')]),table=T('状态项|编辑前示例|编辑后示例','rampKg|30000|31000\nTOW|184500|185500\nconfirmed|旧内容表示|空字符串\nresult|上一次 Result|保留但失效\ngroundChanged|可能为 true|false，草稿仍未确认')),
P('新建航班与默认值','''“新建航班”以 example() 生成完整对象，再替换 id、number 和 source。新对象具有可用的结构、跑道和天气默认值，便于用户从完整模板开始编辑。默认值是本地样例，不代表系统已获取该机场当天资料。

id 使用当前时间形成本地标识，航班号初始化为 LOCAL330。新建操作走 editFlight，因此不会自动形成确认或有效结果。历史列表和最近结果仍属于状态容器中的其他字段，其可用性由签名决定。

默认值与只读值不同。跑道、天气和载荷样例可由用户修改；OEW 则受当前资料包固定值约束。界面通过字段可编辑性和说明文字区分两类信息。''',table=T('默认项目|样例内容|后续处理','航班身份|LOCAL + 时间标识|保持对象区分\n航班号|LOCAL330|用户编辑\n机场|ZUTF / ZSPD / ZSSS|用户填写本次资料\n载荷|250 人及平均质量|按场景修改\n燃油|30000 kg、滑行 500 kg|按计划修改\n跑道气象|人工示例|按资料录入\nOEW|127000 kg|由资料包约束'),diagram=D('pipeline','新建对象的来源',['example() 完整模板','生成本地 id','设置航班号与来源','editFlight','草稿即时显示','等待用户确认'])) ,
P('输入过程中不完整数据的处理','''用户输入不是一次性形成完整对象。清空数字、输入一半机场代码或改变距离单位时，页面会经历短暂的不完整状态。草稿允许这些中间状态存在，确认动作则要求所有当前规则通过。若每次按键都强制回退到旧合法值，用户将难以编辑多位数字。

当前界面将空数值表示为 NaN，字段显示为空，validate 报告非有限数问题。重量卡片格式化函数对无效派生量使用占位符，而不是显示“NaN kg”。用户继续填入合法数字后，派生卡片自然恢复。

即时保存不等于文件一定可以再次作为合法输入导入。导出的草稿可能尚未满足校验，重新导入时仍经过完整 parseFlight。用户进行跨机交换前，先完成确认可以尽早发现输入问题。''',diagram=D('state','输入中间状态与提交状态',['完整草稿','编辑中的不完整草稿','校验通过的草稿','已确认计划'],[(0,1,'清空或改写字段'),(1,2,'补全合法输入'),(2,3,'保存并确认'),(3,1,'继续修改')]),table=T('阶段|允许中间值|业务出口','正在输入|可以暂时不完整|显示即时错误\n保存草稿|保持当前编辑|本机恢复用途\n确认计划|全部规则通过|同步原生页面\n执行计算|确认与输入匹配|生成 Result\n导入文件|整体通过校验|替换当前草稿')) ,refs=['L-U','L-S','L-F'])
S(c,'校验规则的组织与实现',
P('从对象结构到业务约束','''validate 分阶段执行。第一层检查输入是否为对象、模式与机型身份是否匹配、文本与数字类型是否正确；随后检查 runway 和 weather 子对象以及字段类型；基本结构通过后，再执行人数、质量、跑道和气象的业务范围检查。

这种顺序避免在缺少子对象时继续访问深层字段。函数尽量收集同一阶段的多个错误，让用户一次看到相关问题，而不是每次只改一个字段再收到下一条提示。

数据合法性与模型支持范围保持分离。validate 不因为湿跑道就判定文件格式错误；calculate 在其后判断是否有相应速度修正数据。''',diagram=D('pipeline','分层校验路径',['对象与版本','文本和数值类型','子对象存在性','基础格式','业务范围与相互关系','错误集合或合法输入']),table=T('校验层|代表规则|失败含义','容器|对象且不是数组|输入结构错误\n身份|模式 1、机型包匹配|格式或机型不兼容\n类型|有限数字、布尔、文本|值的表示不正确\n格式|机场、日期、跑道编号|字符串含义不符合约定\n范围|人数、质量、气象边界|超出录入范围\n关系|滑行油、声明距离、结构重量|字段之间不一致')),
P('质量约束的相互作用','''单字段合法并不保证组合合法。旅客人数、平均质量和货物都为非负值时，合计 ZFW 仍可能超过结构配置值；停机坪燃油本身在上限内时，加入载荷后的 TOW 也可能超过 MTOW。validate 因此在基本数字检查后调用 weights 检查合计。

固定 OEW 的校验保证当前参考资料包与模型一致。把 OEW 修改为更小值虽然会降低 TOW，却会改变机型配置，不能被当作普通编辑捷径。另一个资料配置可以采用不同 OEW，但需要具有自己的身份和来源。

燃油上限采用当前本地配置常量，滑行耗油不得大于停机坪燃油。容量显示与质量上限可能受密度和取整影响而存在小差别，界面中的显示值不替代校验规则本身。''',table=T('规则|表达式或条件|解释','人数为整数|Integer(pax)|人数不是连续质量\n单人质量|1 ≤ paxKg ≤ 200|当前录入约束\nOEW 固定|oewKg = 127000|对应资料包\n燃油关系|taxiKg ≤ rampKg|起飞油量非负\n零油重|ZFW ≤ 181000|结构配置限制\n起飞重量|TOW ≤ 251000|结构配置限制\n参考表范围|130000 ≤ TOW ≤ 250000|在 calculate 中另行判断'),diagram=D('formula','组合约束依赖质量派生',[['载荷合计','payload = pax × (paxKg + bagKg) + freightKg'],['结构校验','ZFW ≤ MZFW；TOW ≤ MTOW'],['资料范围','massMin ≤ TOW ≤ massMax']])) ,
P('跑道与环境校验的语义','''跑道校验先保证可用距离关系，再检查位置扣减。intersection 必须非负且小于 TORA，因此 effectiveTora 为正。该规则只保证输入自洽，不说明扣减后距离足以满足某次起飞性能要求。

方向允许 0～360°，风速为非负值。气压、气温、标高和坡度有本地输入范围，防止明显异常数据进入公式。范围属于软件录入规则，不能反推为飞机或机场在整个范围内都具有运行适用性。

跑道编号使用两位数字及可选 L、R、C 的格式表达。当前正则检查格式形状，不承担机场数据库核实。因此存在某个编号字符串，不表示该机场真实拥有这条跑道。''',table=T('输入类别|当前规则|规则的边界','跑道编号|两位数字 + 可选 L/R/C|不查询真实机场\nTORA|大于 0 且不超过 10000 m|不计算性能余量\nTODA / ASDA|不小于 TORA|声明距离一致性\n扣减|0 ≤ intersection < TORA|保证有效滑跑距离为正\n方向|0～360°|坐标值合法\n气象与标高|规定的录入范围|不是完整性能包络'),diagram=D('components','校验与资料核实的不同职责',['用户录入','格式和数值校验','自洽 Flight','机场资料服务','权威资料身份'],[(0,1,'当前实现'),(1,2,'合法对象'),(3,4,'来源信息'),(4,0,'录入依据')])) ,
P('错误集合与原子导入','''文件导入使用完整校验结果决定是否替换航班。只要错误集合非空，parseFlight 抛出包含原因的异常，页面保留原计划。这种原子行为避免一份损坏文件先改了机场、后发现重量错误，却留下半新半旧的状态。

表单编辑则不同：它允许用户保留不完整草稿，并通过错误区持续显示问题。两种行为并不矛盾，因为文件导入是外部对象的整体替换，表单编辑是当前对象的逐步构造。

这种边界设计也便于扩展模式迁移。迁移器先在临时对象上完成转换和校验，只有最终对象合法才进入 loadFlight，不让转换的中间值泄漏到当前业务状态。''',diagram=D('sequence','文件错误不污染当前计划',['文件选择器','parseFlight','validate','本地 State'],[(0,1,'完整文本'),(1,2,'解析后的对象'),(2,1,'错误集合'),(1,0,'抛出可读原因'),(0,3,'只更新 notice，保留 flight')]),table=T('入口|允许部分更新|失败后的对象','单字段编辑|是，属于当前草稿|保留用户正在编辑的值\nJSON 导入|否|保持原 Flight\n历史恢复|先取得完整 input|经正常加载路径\n模式迁移|仅在临时对象上|成功后整体提交')) ,refs=['L-F','L-U','L-S'])
S(c,'确认、同步与业务状态转换',
P('确认动作的执行顺序','''confirmFlight 先校验当前 Flight，失败时只更新通知并返回 false。成功后，将当前 signature 写入 confirmed，清除 groundChanged，设置确认消息，再调用 applyToEfb 和 publish。确认因此同时建立业务身份和页面共享投影。

确认并不生成新的性能结果。它只说明当前输入满足规则并已提交给相关页面。runCalculation 仍是独立动作，读取确认后的当前输入和资料包生成 Result。将二者分开，可以让用户在多个页面核对同一计划而不每次都触发计算。

当前实现是在单浏览器线程中顺序执行，没有跨进程事务。未来若 applyToEfb 改为远端异步接口，需增加同步状态和失败回执，不能把现有同步函数直接视为分布式原子提交。''',diagram=D('sequence','确认事务在当前单线程中的顺序',['确认按钮','confirmFlight','applyToEfb','publish'],[(0,1,'用户确认'),(1,1,'validate'),(1,1,'记录 confirmed'),(1,2,'映射原生数据'),(1,3,'本机保存与通知')]),table=T('步骤|修改内容|与计算的关系','校验|得到错误或通过|保证输入合法\n记录签名|confirmed|锁定确认对象\n清除地面变化|groundChanged=false|建立新计划基准\n兼容映射|Store 与目标|相关页面同一计划\n发布|存储和 UI 通知|不自动生成 Result')),
P('确认后的目标初始化','''确认计划把燃油、零油重和全重等目标写入开发宿主，并把原生 fuelImported、payloadImported 标志置为 false。原生页面可以据此将新的航班计划作为待导入目标处理，而不是继续把旧的“已导入”状态用于新航班。

目标初始化使用同一份 Flight 和同一次 weights 返回值。这样仪表盘 ZFW、签派资料中的载荷合计和地面计划条具有共同来源。不能在每个页面分别采用不同的旅客平均质量重新计算同一个计划。

开发宿主还为当前油箱显示分配样例值，方便本地页面阅读。设计上该分配属于宿主演示行为，与计划目标本身分开命名和说明。接入真实后端时，应由真实快照替换样例当前值，而不是把计划同步当作实际油量回执。''',table=T('同步目标|来自当前计划|后续使用者','燃油目标|rampKg|原生燃油页\nZFW 目标|weights.zfw|载重页\nGW 目标|weights.ramp|原生重量显示\n每人质量|paxKg|原生载重规则\n每件平均行李质量|bagKg|原生载重规则\n兼容导入标志|重置为待导入|原生计划导入流程'),diagram=D('components','一次确认生成多种一致投影',['确认 Flight','weights 结果','仪表盘','本地 OFP','燃油目标','载重目标'],[(0,1,'唯一质量计算'),(1,2,'摘要'),(1,3,'文档'),(0,4,'计划油量'),(1,5,'质量目标')])) ,
P('计算资格与地面变化','''runCalculation 的前置条件是 confirmed 与当前 signature 完全相同，且 groundChanged 为 false。该判断在状态层执行，因此即使某个页面错误地让按钮保持可点击，也不会绕过业务规则直接产生新结果。

地面目标变化事件只在确认存在且尚未标记变化时设置 groundChanged。这避免同一次地面调整中的连续写入重复产生相同通知。随后 currentResult 失效，报告出口和历史保存同步关闭。

用户读取新燃油目标或修改其他输入后，editFlight 清除确认；再次确认重新建立基准。这个循环保证“当前计划”是一个有可见提交点的对象，而不是所有页面同时可写的松散变量集合。''',diagram=D('state','确认与地面变化的组合状态',['未确认草稿','已确认 / 地面未变','计算结果有效','地面已变','输入已改'],[(0,1,'确认'),(1,2,'计算'),(2,3,'目标变化'),(2,4,'编辑'),(3,0,'读取目标'),(4,1,'重新确认')]),table=T('confirmed 匹配|groundChanged|计算资格','否|任意|要求先确认\n是|true|要求核对地面变化\n是|false|允许执行当前参考计算\n历史恢复后为空|false|仍需重新确认')),
P('确认状态的恢复与显示','''程序初始化读取本机状态后，initializeLocal 只在 confirmed 与当前 signature 一致时重新映射原生页面。未确认草稿可以恢复到工作台，但不会因此自动变成仪表盘中的确认航班。这个区别让草稿保存和业务提交各自保持意义。

签名比较包含当前资料包和内核版本，因而升级资料后旧确认可能不再匹配。用户仍能查看草稿并重新确认，而不必丢弃全部输入。界面应把这种情况解释为需要重建当前确认，而不是简单说文件已经损坏。

存储错误优先显示，防止一条“确认成功”消息掩盖本机保存失败。当前内存状态仍可继续使用，但用户应通过 JSON 出口保留工作。''',diagram=D('pipeline','刷新后的状态恢复',['读取本机记录','校验 Flight','形成当前 State','比较确认签名','匹配则重建原生投影','显示草稿或确认计划']),table=T('恢复内容|确认签名情况|运行表现','合法未确认草稿|空或不匹配|工作台继续编辑\n合法已确认计划|当前签名匹配|恢复原生投影\n资料包已变化|旧确认不匹配|重新确认当前资料\n存储内容不合法|校验失败|保留错误说明与样例初值\n保存失败|内存仍存在|提示文件导出')) ,refs=['L-S','L-F','L-U'])
S(c,'文件交换与报告生成',
P('文件选择与重复导入','''工作台使用浏览器文件选择控件读取 JSON。处理器等待 file.text() 得到完整文本，再交给 parseFlight；成功后调用 loadFlight，失败时更新 notice。处理结束后清空文件输入控件的 value，使用户可以再次选择同一个已修正文件。

文件控件的 accept 属性用于帮助用户选择 .json，并不能代替内容校验。扩展名正确的文件仍可能含有错误模式或无效数值，导入器始终根据内容判断。界面把失败与“原航班保留”一起说明，减少用户担心当前工作已被覆盖。

导出航班 JSON 直接使用当前 Flight，不需要在线服务。导出文件适合备份和跨浏览器迁移，导入之后仍遵循草稿、确认和计算的正常流程。''',diagram=D('sequence','文件选择处理器',['文件控件','浏览器 File','parseFlight','状态层'],[(0,1,'选择文件'),(1,2,'text() 完整内容'),(2,3,'合法 Flight'),(3,0,'状态消息'),(0,0,'清空控件值，允许重选')]),table=T('处理环节|目的|失败行为','选择过滤|提示 JSON 类型|仍以内容校验为准\n完整读取|获得文本|显示读取错误\n解析和校验|形成合法对象|保留原航班\n载入草稿|统一状态路径|撤销旧确认\n重置文件控件|允许重新选择同一文件|不删除用户文件')),
P('报告的数据装配','''reportHtml 从 currentResult 取得当前有效对象，读取其中的输入、质量、参考速度、辅助量、版本和生成时间。报告不重新调用 calculate，因此不会在导出时形成另一组与屏幕不同的计算值。

报告正文先显示结果性质与缺少的性能能力，再列航班和跑道身份、质量与 V2 参考、压力高度、风分量、扣减后 TORA，最后附完整输入及结果快照。短摘要便于阅读，完整快照便于追溯。

V2 在报告中同时显示小数参考和上取整数，二者来自同一底层结果。上取整仅是显示方式，不能补足未建模的风、温度、坡度或跑道限制修正。''',diagram=D('layers','报告的内容层次',['结果性质与能力范围','航班、日期、机场及跑道','质量、速度参考与辅助量','资料包、内核版本和生成时间','完整输入与结果 JSON 快照']),table=T('报告区块|数据来源|目的','航班摘要|Result.input|识别计算对象\n质量与速度|Result.weights / v2|解释主要输出\n环境辅助量|同一 Result|保留输入环境关系\n版本信息|profileVersion / engineVersion|识别规则与资料\n完整快照|Result 序列化|保留可追溯上下文')),
P('HTML 安全呈现与打印','''报告模板中的用户文本经过 esc 转义，处理 &、尖括号以及引号。航班号和航路即使包含 HTML 片段，也应作为文字显示。当前本地 loadsheet 同样使用这一转义入口，避免原生 HTML 阅读器执行用户输入中的标记。

打印功能先生成报告，再打开独立窗口写入 HTML。窗口被浏览器阻止时抛出可读错误，用户可改用“导出报告 HTML”。打印媒体样式隐藏按钮，使纸面内容保留报告而不带交互控件。

报告样式采用普通文档宽度、白色背景和深色文字，与原生深色 EFB 区分。这样无需在打印时对整幅屏幕截图做反色处理，也不会丢失可选择的文字。''',table=T('处理对象|实现方式|效果','用户文本|HTML 字符转义|按文字而不是标签显示\nJSON 快照|转义后置于 pre|保留结构化内容\n报告窗口|window.open 后写入完整文档|独立阅读与打印\n弹窗受阻|抛出操作提示|可切换 HTML 下载\n打印按钮|@media print 隐藏|不进入纸面正文\n下载文件|Blob 与安全文件名|浏览器本地保存'),diagram=D('pipeline','从有效结果到打印文档',['currentResult','组装报告数据','转义用户文本','生成白底 HTML','打开报告窗口','打印或保存 PDF'])) ,
P('历史记录与文件出口的组合','''本机历史适合快速回到最近一次计算的输入，JSON 适合继续编辑，HTML 适合阅读。三种方式可以组合使用，但没有一种自动代替另外两种。历史记录被截断后，已导出的文件仍可保留；HTML 文件则不能直接作为 Flight 导入。

归档操作把结果快照放在历史数组前端，并保留原来的生成时间。恢复按钮明确标注“需重算”，让用户知道它恢复的是输入而不是当前计算资格。新结果生成后可以再次保存，形成新的记录。

这种设计使技术追溯不依赖记住用户曾经点击过什么。记录对象已经包含输入、结果和版本；使用说明只需要解释如何保存、恢复和导出，而不必让用户另行维护一份操作任务表。''',diagram=D('components','同一计算记录的不同后续用途',['当前有效 Result','本机历史','恢复为 Flight','结果 JSON','HTML 报告'],[(0,1,'近期保存'),(1,2,'恢复输入'),(0,3,'结构化归档'),(0,4,'阅读归档')]),table=T('后续目的|适合使用的出口|再次进入软件','继续修改航班|航班 JSON|工作台导入\n比较近期输入|本机历史|恢复后确认重算\n保留计算上下文|结果 JSON|作为结果记录阅读\n打印或发送可读说明|HTML 报告 / 打印 PDF|浏览器阅读\n迁移到另一浏览器|航班 JSON|不依赖原站点存储')) ,refs=['L-S','L-U','L-F'])

c=C(8,'仪表盘与签派模块详细设计','第二篇  分模块详细设计')
S(c,'航班摘要与聚合视图',
P('FlightWidget 的显示模型','''FlightWidget 从原生 simbrief.data 读取航班号、出发和到达机场、时刻、航路、巡航高度、平均风和重量。airframeInfo 提供机型显示名称，flightProgress 提供进度值。组件把这些来源组合成用户的航班摘要。

时刻以秒级时间戳字符串进入原生模型，组件转换为 UTC 小时和分钟并附 Z。巡航高度除以 100 后以 FL 格式显示。零油重从原生字符串转换为数字，再按吨级显示精度格式化。格式化负责阅读，不改变领域模型中的 kg 数值。

本地构建把原导入入口转为“编辑本地航班”。点击后直接进入工作台，不发起 SimBrief 请求。未确认计划时保留明确空态，确认后显示兼容映射得到的资料。''',diagram=D('components','航班摘要的数据来源',['simbrief.data 兼容投影','airframeInfo','flightProgress','FlightWidget','本地工作台'],[(0,3,'航班资料'),(1,3,'机型名称'),(2,3,'进度'),(3,4,'编辑入口')]),table=T('显示项|原生来源|显示处理','起降机场|departingAirport / arrivingAirport|ICAO 与名称\n航班号|airline + flightNum|身份摘要\n计划时刻|schedOut / schedIn|UTC HHMMZ\n巡航高度|cruiseAltitude|转换为 FL\n零油重|estZeroFuelWeight|字符串解析与吨级格式\n平均风|weather.avgWindDir / avgWindSpeed|方向 / 速度')),
P('进度显示与地理状态','''原生 Efb 使用当前位置到目的地距离与起终点距离计算 flightPlanProgress，再写入共享切片。它表达相对于起终点的地理进度，不是完整航路各航段距离累计。绕飞、复杂航路或数据缺失时，两种进度定义可能不同。

本地宿主提供人工经纬度，兼容计划又没有完整导航航段，因此仪表盘进度只属于开发展示。它不能作为真实航路执行的证据，也不用于驱动本地 V2 参考计算。模块之间只共享必要信息，避免一个看似直观的图形变成隐含控制输入。

摘要页保留出发、到达机场和时刻，有助于用户识别当前计划。航班确认才是数据同步入口，单纯在仪表盘停留不会自动从外部服务替换计划。''',diagram=D('formula','原生进度的基本关系',[['地理距离','Dtotal = distance(departure, arrival)'],['剩余距离','Dremain = distance(position, arrival)'],['显示进度','progress = max(0, (Dtotal - Dremain) / Dtotal × 100)']]),table=T('数据项|含义|模块使用方式','当前位置|宿主经纬度|地理进度输入\n起终点位置|航班机场位置|参考距离\nflightPlanProgress|派生百分比|进度条显示\n本地航路文字|手工描述|不参与航段跟踪\n本地参考计算|重量与构型等|不依赖仪表盘进度')),
P('提醒组件与个性化排列','''仪表盘右侧的 RemindersWidget 聚合天气、固定航图、维护和检查单提醒。每种提醒是独立组件，按一组持久化键的顺序渲染。用户调整的是阅读顺序，不是业务执行顺序。

REMINDER_WIDGET_ORDERED_KEYS 保存已排列的类型名称。组件初始化时补入新版本增加但旧保存列表缺少的提醒键，使扩展组件不会因为用户曾保存旧顺序而永久消失。上下移动操作重新排列键数组，再保存为字符串。

提醒卡片以摘要和跳转为主。复杂编辑在对应模块完成，例如检查单条目在检查单页面维护，航图在导航页管理。聚合组件由此保持较小职责，避免成为第二套业务实现。''',diagram=D('tree','仪表盘提醒组件',['RemindersWidget',['Weather','出发天气','到达天气'],['Pinned Charts','已固定航图','导航入口'],['Maintenance','故障摘要','故障页入口'],['Checklists','程序提醒','检查单入口']]),table=T('提醒类别|数据所属模块|仪表盘职责','天气|天气与仪表盘状态|摘要显示\n固定航图|导航状态|显示和跳转\n维护|故障编排|状态摘要\n检查单|trackingChecklists|程序提醒\n排列顺序|用户持久化设置|个性化阅读')) ,refs=['EFB','L-S','PAD'])
S(c,'签派资料与 OFP 阅读器',
P('签派页面的组成','''Dispatch 模块提供本地航班、运行飞行计划和机型概览三个入口。本地航班工作台是新增输入页面；OFP 使用原生 LoadSheetWidget 阅读兼容数据中的 loadsheet；概览使用机型配置展示飞机信息。

模块把输入编辑与资料阅读分开。工作台中的错误或未确认状态不应被一个看起来完整的 OFP 文档遮掩。确认之后重新生成本地 loadsheet，使文档与提交的计划一致。OFP 标题沿用原生页面名称，文档内部明确显示 LOCAL FLIGHT 和本地来源。

本地签派资料不是完整运行飞行计划生成器。它没有计算航路燃油、风优化、航路限制或签派批准，而是把当前本地输入组织为可读文档。''',diagram=D('components','签派模块的编辑与阅读分离',['本地工作台','confirmFlight','loadsheet HTML','LoadSheetWidget','机型配置','OverviewPage'],[(0,1,'提交计划'),(1,2,'生成资料'),(2,3,'阅读'),(4,5,'机型概览')]),table=T('子页面|主要数据|主要功能','本地航班|Flight|编辑、确认、文件交换\n运行飞行计划|loadsheet HTML|缩放与滚动阅读\n概览|机型配置|飞机信息展示\n原生状态|dispatchPage.ofpScroll|保留阅读位置')),
P('本地 loadsheet 模板','''applyToEfb 为本地航班生成一个白底 HTML 内容块。文档包含航班号、UTC 日期、起降机场、机型、来源、航路文字，以及 OEW、载荷、ZFW、停机坪油、滑行油和 TOW 的关系。每个质量都来自本次确认的输入。

模板直接解释质量算式，便于阅读者理解合计来自哪里。人工样例中的航路 DCT 文字只作为文本显示，来源行说明其本地计划性质。这样的文档可支持软件演示和资料核对，但不会借用原生 OFP 页面名称暗示存在外部签派批准。

模板的 h1、p 等元素设置深色文字，以适应原生深色界面内的白底内容区。业务内容和外层阅读器各自控制样式，避免全局主题把正文变成白底白字。''',table=T('模板内容|取值来源|例子','航班身份|number / date|DEMO330、2026-10-03\n机场与机型|from / to / profile|ZUTF → ZSPD、A330-941\n来源|source|local-example\n无油重|OEW + payload|127000 + 28000 = 155000 kg\n起飞油量|rampKg - taxiKg|30000 - 500 = 29500 kg\n起飞重量|ZFW + 起飞油量|184500 kg\n人数|pax|250'),diagram=D('layers','本地签派资料的信息顺序',['航班身份与机型','来源说明与航路文字','载荷及零油重关系','停机坪油、滑行油和起飞重量','本地计划与宿主状态说明'])) ,
P('缩放和阅读位置','''LoadSheetWidget 使用 LOADSHEET_FONTSIZE 保存字体大小，初始值为 14。放大和缩小以 2 为步长，在 14 至 26 的范围内调整；图片宽度随操作以 5 个百分点变化，初始为 60%。文档内容不是通过缩放整个 EFB 画布实现阅读缩放。

ofpScroll 保存在 dispatchPage 切片。ScrollableContainer 在滚动停止时记录位置，页面再次呈现时把它作为 initialScroll。这样用户查看较长资料后切换到其他模块，再返回时可以继续阅读。

文字大小属于持久偏好，图片尺寸属于组件局部状态，滚动位置属于运行状态。三个量的生命周期不同，也解释了为什么刷新整个应用与仅切换页面可能产生不同的恢复表现。''',diagram=D('entity','OFP 阅读状态分布',[['持久化偏好','LOADSHEET_FONTSIZE','14～26，步长 2'],['组件局部状态','imageSize','初始 60%，每次变化 5%'],['Redux 页面状态','dispatchPage.ofpScroll','滚动停止时保存']],[(0,1,'同次缩放动作'),(2,0,'共同影响阅读视图')]),table=T('交互|更新对象|反馈','点击放大|fontSize、imageSize|文字及图片更大\n点击缩小|fontSize、imageSize|回到更小显示\n滚动文档|ofpScroll|保留阅读位置\n切换业务页|组件与共享状态各自保留|返回可继续阅读\n重新装载应用|持久偏好重新读取|运行状态按启动规则恢复')),
P('HTML 阅读边界','''原生阅读器通过 dangerouslySetInnerHTML 呈现 loadsheet，因此内容生成位置是重要边界。本地模板仅把经过转义的用户字段放入已知结构，用户输入不直接成为 HTML 标签。若未来读取外部 HTML，还需要独立的内容清理和资源策略。

阅读器负责字体、图片尺寸及滚动，不负责证明文档内容真实性。来源行、版本及计划身份由生成模块提供。将展示控件和资料来源分开，可以避免“某文件能在 OFP 页显示”被误解为文件经过业务认证。

无航班资料时，阅读器显示明确空态。用户应先在本地工作台确认航班；直接进入 OFP 页不会自行创建一份计划，也不会自动登录外部服务。''',diagram=D('pipeline','本地 HTML 进入阅读器的边界',['Flight 文本字段','字符转义','已知 HTML 模板','原生 loadsheet 字段','HTML 阅读控件','缩放与滚动显示']),table=T('职责|承担组件|边界','生成业务内容|applyToEfb|来自已确认计划\n转义用户输入|esc|保持文本语义\n呈现 HTML|LoadSheetWidget|不验证资料来源\n阅读交互|字体及滚动状态|不改写计划\n外部 HTML 接入|未来资料适配器|需要额外内容策略')) ,refs=['DIS','EFB','L-S'])
S(c,'天气与航班资料协同',
P('天气组件的数据模型','''WeatherWidget 分别处理出发与目的机场。组件读取气象源、气压显示单位、是否使用彩色 METAR 等设置，使用解析后的 METAR 对象展示风、气温、露点和气压，也保留原始报文显示方式。

解析对象包含原文、观测时间、风、能见度、云、温度、露点和气压等属性。没有可用报文时使用空对象形状与错误状态维持组件结构，页面显示“不适用”等反馈，而不是把零初值当成真实天气观测。

本地宿主的 METAR 调用返回空文本，因此本机演示不伪造实时气象。用户在离线参考页手工输入的 weather 是航班计算输入，与仪表盘外部天气组件的资料状态分开。''',diagram=D('components','天气显示与本地计算输入的分离',['天气提供商','METAR 解析对象','WeatherWidget','用户手工天气','Flight.weather','本地参考计算'],[(0,1,'资料响应'),(1,2,'显示'),(3,4,'录入'),(4,5,'计算输入')]),table=T('天气信息|显示来源|用途','原始 METAR|提供商报文|阅读原文\n风温压露点|解析对象|天气卡片\n观测时间|报文时间|时效说明\n本地 weather|用户输入|参考计算上下文\n空天气|无报文或服务不可用|明确无数据状态')),
P('机场选择和气压显示','''天气组件允许使用航班机场或用户选择的机场。departure 和 destination 各自保存对应资料，使两张卡片可以保持独立。用户修改卡片机场是资料检索动作，不应隐式改变 Flight 的起降机场。

气压显示支持自动选择或固定单位。原生代码根据机场代码前缀选择常用显示方式，最终从同一个解析对象读取 hg 或 mb 值。显示单位变化并不产生一份新天气，也不更改气象来源时刻。

这种局部资料检索适合辅助阅读，但将天气用于计算时仍需要明确采用动作和输入更新。当前离线参考页由用户填写气象，不从天气卡片自动复制全部值。''',table=T('选择或显示项|状态归属|对航班的影响','航班出发机场|确认计划投影|作为默认资料上下文\n用户检索机场|仪表盘天气状态|不自动改写起飞机场\n气压单位|持久化设置|改变显示格式\n原始报文开关|对应卡片偏好|改变阅读方式\n参考页天气|Flight.weather|参与签名与辅助计算'),diagram=D('sequence','天气卡片中的选择与显示',['用户','天气卡片状态','天气服务','解析显示'],[(0,1,'选择机场'),(1,2,'请求该机场资料'),(2,3,'报文与时间'),(1,3,'显示单位与原文偏好'),(3,0,'展示资料')])) ,
P('资料更新与航班一致性','''航班投影、天气资料和检查单提醒的更新频率不同。仪表盘把它们放在同一屏幕上，但不把它们合并成一个不可分割的数据对象。航班由确认动作更新，天气由资料请求更新，检查单由程序状态更新。

设计上，聚合视图应保留各自的来源和状态。一次天气刷新不应重置检查单，也不应覆盖用户正在编辑的载荷；新的确认航班则应提供新的机场上下文，让资料组件有机会重新选择正确对象。

当前原生组件与本地扩展通过明确投影保持基本一致。更完整的多服务航班会话隔离可进一步用 flightId 与请求标识丢弃旧响应，此项属于关键技术章节讨论的扩展机制。''',diagram=D('lanes','仪表盘三个更新来源',[['航班计划','用户编辑','保存确认','摘要更新'],['天气资料','机场选择','资料响应','天气卡片更新'],['程序状态','检查单动作','状态切片','提醒更新']]),table=T('事件|应更新的内容|不应连带改变的内容','确认新航班|航班投影及机场上下文|无关用户偏好\n天气响应|对应机场天气|载荷与燃油草稿\n勾选检查项|程序及提醒|航班身份\n调整提醒排序|阅读顺序|业务完成状态\n切换显示单位|格式化视图|原始数据身份')) ,refs=['EFB','L-S','PAD'])
